# Generated by Qwen4 (direct vLLM)
import os
import sqlite3
import hashlib
import unittest

# Directory setup
LEGAL_ROOT = "legal_taxonomy"

def create_directory_structure():
    categories = {
        "01_Constitution": [],
        "02_Legislation": ["Acts", "LIs", "Regulations"],
        "03_Case_Law": ["Supreme", "Appeal", "High_Court"],
        "04_Procedure": ["Civil", "Criminal", "Evidence"],
        "05_Specialized_Law": [],
        "06_International_Law": [],
        "07_Legal_Reasoning": []
    }
    
    for category, subdirs in categories.items():
        path = os.path.join(LEGAL_ROOT, category)
        os.makedirs(path, exist_ok=True)
        for subdir in subdirs:
            os.makedirs(os.path.join(path, subdir), exist_ok=True)
    
    # Create example constitution file
    example_content = "# 1992 Constitution\nThis is the supreme law of the land."
    with open(os.path.join(LEGAL_ROOT, "01_Constitution", "1992_Constitution.md"), "w") as f:
        f.write(example_content)

# Database setup
def init_database():
    conn = sqlite3.connect("legal_taxonomy.db")
    cursor = conn.cursor()
    
    cursor.execute('''
        CREATE TABLE IF NOT EXISTS documents (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            category TEXT NOT NULL,
            subcategory TEXT,
            filename TEXT NOT NULL,
            content_hash TEXT NOT NULL,
            supreme_authority_flag INTEGER DEFAULT 0,
            conflict_citation TEXT
        )
    ''')
    
    cursor.execute('''
        CREATE TABLE IF NOT EXISTS relationships (
            document_id INTEGER NOT NULL,
            related_document_id INTEGER NOT NULL,
            relationship_type TEXT NOT NULL,
            FOREIGN KEY (document_id) REFERENCES documents (id),
            FOREIGN KEY (related_document_id) REFERENCES documents (id)
        )
    ''')
    
    # Insert example constitution document
    constitution_path = os.path.join(LEGAL_ROOT, "01_Constitution", "1992_Constitution.md")
    with open(constitution_path, "r") as f:
        content = f.read()
        content_hash = hashlib.md5(content.encode()).hexdigest()
    
    cursor.execute('''
        INSERT INTO documents 
        (category, filename, content_hash, supreme_authority_flag) 
        VALUES (?, ?, ?, ?)
    ''', ("01_Constitution", "1992_Constitution.md", content_hash, 1))
    
    conn.commit()
    conn.close()

# Conflict validation
def validate_document(category, subcategory, filename, content, conflict_citation=None):
    content_hash = hashlib.md5(content.encode()).hexdigest()
    
    if conflict_citation:
        # Verify we have a valid Constitution reference
        conn = sqlite3.connect("legal_taxonomy.db")
        cursor = conn.cursor()
        cursor.execute('''
            SELECT 1 FROM documents 
            WHERE supreme_authority_flag = 1
        ''')
        if not cursor.fetchone():
            raise ValueError("No supreme authority document exists in the database")
        conn.close()
        
        if not conflict_citation.strip():
            raise ValueError("Conflict citation cannot be empty when marking a conflict")
    
    return {
        "category": category,
        "subcategory": subcategory,
        "filename": filename,
        "content_hash": content_hash,
        "conflict_citation": conflict_citation
    }

# Tests
class TestLegalTaxonomy(unittest.TestCase):
    def test_directory_structure(self):
        self.assertTrue(os.path.exists(os.path.join(LEGAL_ROOT, "01_Constitution")))
        self.assertTrue(os.path.exists(os.path.join(LEGAL_ROOT, "02_Legislation", "Acts")))
        self.assertTrue(os.path.exists(os.path.join(LEGAL_ROOT, "03_Case_Law", "Supreme")))
        self.assertTrue(os.path.exists(os.path.join(LEGAL_ROOT, "04_Procedure", "Civil")))
        self.assertTrue(os.path.exists(os.path.join(LEGAL_ROOT, "05_Specialized_Law")))
        self.assertTrue(os.path.exists(os.path.join(LEGAL_ROOT, "06_International_Law")))
        self.assertTrue(os.path.exists(os.path.join(LEGAL_ROOT, "07_Legal_Reasoning")))
        self.assertTrue(os.path.exists(os.path.join(LEGAL_ROOT, "01_Constitution", "1992_Constitution.md")))
    
    def test_database_structure(self):
        conn = sqlite3.connect("legal_taxonomy.db")
        cursor = conn.cursor()
        
        cursor.execute("SELECT name FROM sqlite_master WHERE type='table' AND name='documents'")
        self.assertTrue(cursor.fetchone())
        
        cursor.execute("SELECT name FROM sqlite_master WHERE type='table' AND name='relationships'")
        self.assertTrue(cursor.fetchone())
        
        cursor.execute("SELECT * FROM documents WHERE supreme_authority_flag = 1")
        self.assertTrue(cursor.fetchone())
        
        conn.close()
    
    def test_conflict_validation(self):
        # Valid case
        doc = validate_document(
            "03_Case_Law", 
            "Supreme", 
            "test_case.md", 
            "Test content",
            "1992 Constitution, Article 5"
        )
        self.assertEqual(doc["conflict_citation"], "1992 Constitution, Article 5")
        
        # Invalid case - conflict without citation
        with self.assertRaises(ValueError):
            validate_document(
                "03_Case_Law", 
                "Supreme", 
                "test_case.md", 
                "Test content",
                ""
            )
        
        # Non-conflict case
        doc = validate_document(
            "03_Case_Law", 
            "Supreme", 
            "test_case.md", 
            "Test content"
        )
        self.assertIsNone(doc["conflict_citation"])

if __name__ == "__main__":
    create_directory_structure()
    init_database()
    unittest.main(exit=False)